using System.Net;using System.Net.Mail;using System.Net.Http.Json;using Microsoft.Extensions.Options;using UAF.Application.Features.Notifications;
namespace UAF.Infrastructure.Notifications;
public sealed class NotificationDeliveryOptions{public const string SectionName="NotificationDelivery";public SmtpDeliveryOptions Smtp{get;set;}=new();public SmsDeliveryOptions Sms{get;set;}=new();}
public sealed class SmtpDeliveryOptions{public string? Host{get;set;}public int Port{get;set;}=587;public bool EnableSsl{get;set;}=true;public string? Username{get;set;}public string? Password{get;set;}public string? From{get;set;}}
public sealed class SmsDeliveryOptions{public string? Endpoint{get;set;}public string? ApiKey{get;set;}public string? Sender{get;set;}}
public sealed class SmtpEmailSender:IEmailSender{private readonly SmtpDeliveryOptions _o;public SmtpEmailSender(IOptions<NotificationDeliveryOptions> o)=>_o=o.Value.Smtp;public async Task SendAsync(string to,string subject,string body,CancellationToken ct){if(string.IsNullOrWhiteSpace(_o.Host)||string.IsNullOrWhiteSpace(_o.From))throw new InvalidOperationException("SMTP is not configured.");using var c=new SmtpClient(_o.Host,_o.Port){EnableSsl=_o.EnableSsl};if(!string.IsNullOrWhiteSpace(_o.Username))c.Credentials=new NetworkCredential(_o.Username,_o.Password);using var m=new MailMessage(_o.From,to,subject,body);ct.ThrowIfCancellationRequested();await c.SendMailAsync(m,ct);}}
public sealed class HttpSmsSender:ISmsSender{private readonly HttpClient _http;private readonly SmsDeliveryOptions _o;public HttpSmsSender(HttpClient h,IOptions<NotificationDeliveryOptions> o){_http=h;_o=o.Value.Sms;}public async Task SendAsync(string to,string message,CancellationToken ct){if(!Uri.TryCreate(_o.Endpoint,UriKind.Absolute,out var endpoint)||string.IsNullOrWhiteSpace(_o.ApiKey))throw new InvalidOperationException("SMS gateway is not configured.");using var req=new HttpRequestMessage(HttpMethod.Post,endpoint);req.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",_o.ApiKey);req.Content=JsonContent.Create(new{to,message,sender=_o.Sender});using var res=await _http.SendAsync(req,ct);res.EnsureSuccessStatusCode();}}
